      "sourceName": "Gambit",
      "description": "The NOLA Project presents the comedic and family-friendly version of the horror tale. The adaptation was written by former company actor Pete McElligott, who also wrote their versions of “Frankenstein” and “The Legend of Sleepy Hollow.” At Greenway Station on the Lafitte Greenway. Find tickets and information at nolaproject.com/mummy .",
